)

func TestEngine_NewEngine(t *testing.T) {
	ctx := context.Background()

	policy, err := os.ReadFile("../testdata/rbac.rego")
	require.NoError(t, err)

	data, err := os.ReadFile("../testdata/rbac.json")
	require.NoError(t, err)

	engine, err := newEngine(ctx, zaptest.NewLogger(t), withPolicySource(policySource(string(policy))), withDataSource(dataSource(string(data)), 5*time.Second))
	require.NoError(t, err)
	require.NotNil(t, engine)
}

func TestEngine_IsAllowed(t *testing.T) {
	var tests = []struct {
		name     string
		input    string
		expected bool
	}{
		{
			name: "admin is allowed to create",
			input: `{
                "authentication": {
                    "method": 5,
                    "metadata": {
                        "io.flipt.auth.role": "admin"
                    }
                },
                "request": {
                    "action": "create",
                    "resource": "flag"
                }
            }`,
			expected: true,
		},
		{
			name: "admin is allowed to read",
			input: `{
                "authentication": {
                    "method": 5,
                    "metadata": {
                        "io.flipt.auth.role": "admin"
                    }
                },
                "request": {
                    "action": "read",
                    "resource": "flag"
                }
            }`,
			expected: true,
		},
		{
			name: "editor is allowed to create flags",
			input: `{
                "authentication": {
                    "method": 5,
                    "metadata": {
                        "io.flipt.auth.role": "editor"
                    }
                },
                "request": {
                    "action": "create",
                    "resource": "flag"
                }
            }`,
			expected: true,
		},
		{
			name: "editor is allowed to read",
			input: `{
                "authentication": {
                    "method": 5,
                    "metadata": {
                        "io.flipt.auth.role": "editor"
                    }
                },
                "request": {
                    "action": "read",
                    "resource": "flag"
                }
            }`,
			expected: true,
		},
		{
			name: "editor is not allowed to create namespaces",
			input: `{
                "authentication": {
                    "method": 5,
                    "metadata": {
                        "io.flipt.auth.role": "editor"
                    }
                },
                "request": {
                    "action": "create",
                    "resource": "namespace"
                }
            }`,
			expected: false,
		},
		{
			name: "viewer is allowed to read",
			input: `{
                "authentication": {
                    "method": 5,
                    "metadata": {
                        "io.flipt.auth.role": "viewer"
                    }
                },
                "request": {
                    "action": "read",
                    "resource": "segment"
                }
            }`,
			expected: true,
		},
		{
			name: "viewer is not allowed to create",
			input: `{
                "authentication": {
                    "method": 5,
                    "metadata": {
                        "io.flipt.auth.role": "viewer"
                    }
                },
                "request": {
                    "action": "create",
                    "resource": "flag"
                }
            }`,
			expected: false,
		},
		{
			name: "namespaced_viewer is allowed to read in namespace",
			input: `{
                "authentication": {
                    "method": 5,
                    "metadata": {
                        "io.flipt.auth.role": "namespaced_viewer"
                    }
                },
                "request": {
                    "action": "read",
                    "resource": "flag",
                    "namespace": "foo"
                }
            }`,
			expected: true,
		},
		{
			name: "namespaced_viewer is not allowed to read in unexpected namespace",
			input: `{
                "authentication": {
                    "method": 5,
                    "metadata": {
                        "io.flipt.auth.role": "namespaced_viewer"
                    }
                },
                "request": {
                    "action": "read",
                    "resource": "flag",
                    "namespace": "bar"
                }
            }`,
			expected: false,
		},
		{
			name: "namespaced_viewer is not allowed to read in without namespace scope",
			input: `{
                "authentication": {
                    "method": 5,
                    "metadata": {
                        "io.flipt.auth.role": "namespaced_viewer"
                    }
                },
                "request": {
                    "action": "read",
                    "resource": "flag"
                }
            }`,
			expected: false,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			policy, err := os.ReadFile("../testdata/rbac.rego")
			require.NoError(t, err)

			data, err := os.ReadFile("../testdata/rbac.json")
			require.NoError(t, err)

			ctx, cancel := context.WithCancel(context.Background())
			t.Cleanup(cancel)
			engine, err := newEngine(ctx, zaptest.NewLogger(t), withPolicySource(policySource(string(policy))), withDataSource(dataSource(string(data)), 5*time.Second))
			require.NoError(t, err)

			var input map[string]interface{}

			err = json.Unmarshal([]byte(tt.input), &input)
			require.NoError(t, err)

			allowed, err := engine.IsAllowed(ctx, input)
			require.NoError(t, err)
			require.Equal(t, tt.expected, allowed)
		})
	}
}

func TestEngine_IsAuthMethod(t *testing.T) {
	var tests = []struct {
		name     string
		input    authrpc.Method
		expected bool
	}{
		{name: "token", input: authrpc.Method_METHOD_TOKEN, expected: true},
		{name: "oidc", input: authrpc.Method_METHOD_OIDC, expected: true},
		{name: "k8s", input: authrpc.Method_METHOD_KUBERNETES, expected: true},
		{name: "kubernetes", input: authrpc.Method_METHOD_KUBERNETES, expected: true},
		{name: "github", input: authrpc.Method_METHOD_GITHUB, expected: true},
		{name: "jwt", input: authrpc.Method_METHOD_JWT, expected: true},
		{name: "none", input: authrpc.Method_METHOD_OIDC, expected: false},
	}
	data, err := os.ReadFile("../testdata/rbac.json")
	require.NoError(t, err)
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			ctx, cancel := context.WithCancel(context.Background())
			t.Cleanup(cancel)

			input := map[string]any{
				"authentication": authrpc.Authentication{Method: tt.input},
			}

			policy := fmt.Sprintf(`package flipt.authz.v1

            import rego.v1

            default allow := false

            allow if {
               flipt.is_auth_method(input, "%s")
            }
            `, tt.name)

			engine, err := newEngine(ctx, zaptest.NewLogger(t), withPolicySource(policySource(policy)), withDataSource(dataSource(string(data)), 5*time.Second))
			require.NoError(t, err)

			allowed, err := engine.IsAllowed(ctx, input)
			require.NoError(t, err)
			require.Equal(t, tt.expected, allowed)
		})
	}
}

type policySource string

func (p policySource) Get(context.Context, source.Hash) ([]byte, source.Hash, error) {
	return []byte(p), nil, nil
}

type dataSource string

func (d dataSource) Get(context.Context, source.Hash) (data map[string]any, _ source.Hash, _ error) {
	return data, nil, json.Unmarshal([]byte(d), &data)
}

package server

import (
	"context"

	"go.flipt.io/flipt/errors"
	"go.flipt.io/flipt/internal/storage"
	flipt "go.flipt.io/flipt/rpc/flipt"
	"go.uber.org/zap"
	empty "google.golang.org/protobuf/types/known/emptypb"
)

// GetNamespace gets a namespace
func (s *Server) GetNamespace(ctx context.Context, r *flipt.GetNamespaceRequest) (*flipt.Namespace, error) {
	s.logger.Debug("get namespace", zap.Stringer("request", r))
	namespace, err := s.store.GetNamespace(ctx, storage.NewNamespace(r.Key, storage.WithReference(r.Reference)))
	s.logger.Debug("get namespace", zap.Stringer("response", namespace))
	return namespace, err
}

// ListNamespaces lists all namespaces
func (s *Server) ListNamespaces(ctx context.Context, r *flipt.ListNamespaceRequest) (*flipt.NamespaceList, error) {
	s.logger.Debug("list namespaces", zap.Stringer("request", r))

	ref := storage.ReferenceRequest{Reference: storage.Reference(r.Reference)}
	results, err := s.store.ListNamespaces(ctx, storage.ListWithParameters(ref, r))
	if err != nil {
		return nil, err
	}

	resp := flipt.NamespaceList{
		Namespaces: results.Results,
	}

	total, err := s.store.CountNamespaces(ctx, ref)
	if err != nil {
		return nil, err
	}

	resp.TotalCount = int32(total)
	resp.NextPageToken = results.NextPageToken

	s.logger.Debug("list namespaces", zap.Stringer("response", &resp))
	return &resp, nil
}

// CreateNamespace creates a namespace
func (s *Server) CreateNamespace(ctx context.Context, r *flipt.CreateNamespaceRequest) (*flipt.Namespace, error) {
	s.logger.Debug("create namespace", zap.Stringer("request", r))
	namespace, err := s.store.CreateNamespace(ctx, r)
	s.logger.Debug("create namespace", zap.Stringer("response", namespace))
	return namespace, err
}

// UpdateNamespace updates an existing namespace
func (s *Server) UpdateNamespace(ctx context.Context, r *flipt.UpdateNamespaceRequest) (*flipt.Namespace, error) {
	s.logger.Debug("update namespace", zap.Stringer("request", r))
	namespace, err := s.store.UpdateNamespace(ctx, r)
	s.logger.Debug("update namespace", zap.Stringer("response", namespace))
	return namespace, err
}

// DeleteNamespace deletes a namespace
func (s *Server) DeleteNamespace(ctx context.Context, r *flipt.DeleteNamespaceRequest) (*empty.Empty, error) {
	s.logger.Debug("delete namespace", zap.Stringer("request", r))
	namespace, err := s.store.GetNamespace(ctx, storage.NewNamespace(r.Key))
	if err != nil {
		return nil, err
	}

	// if namespace is not found then nothing to do
	if namespace == nil {
		return &empty.Empty{}, nil
	}

	if !r.GetForce() && namespace.Protected {
		return nil, errors.ErrInvalidf("namespace %q is protected", r.Key)
	}

	if !r.GetForce() {
		// if any flags exist under the namespace then it cannot be deleted
		count, err := s.store.CountFlags(ctx, storage.NewNamespace(r.Key))
		if err != nil {
			return nil, err
		}

		if count > 0 {
			return nil, errors.ErrInvalidf("namespace %q cannot be deleted; flags must be deleted first", r.Key)
		}
	}

	if err := s.store.DeleteNamespace(ctx, r); err != nil {
		return nil, err
	}

	return &empty.Empty{}, nil
}

